int W = 1;
int H = 1;
OccupancyRT.GetRenderTargetSize(W, H);
bool validSize = (W > 0 && H > 0);
bool validUV = (ScreenUV.x >= 0.0f && ScreenUV.x < 1.0f && ScreenUV.y >= 0.0f && ScreenUV.y < 1.0f);
float2 safeUV = saturate(ScreenUV);
int safeW = max(W, 1);
int safeH = max(H, 1);
int2 px = min(int2(safeUV * float2(safeW, safeH)), int2(safeW - 1, safeH - 1));
bool shouldWrite = validSize && validUV;
OccupancyRT.SetRenderTargetValue(shouldWrite, px.x, px.y, float4(1.0f, 0.0f, 0.0f, 1.0f));
OutDummy = shouldWrite ? 1.0f : 0.0f;
